  const yAxisLabel = props.yAxisLabel || 'Share of Sales %';
  const sourceText = props.sourceText || 'Source: EU Trade Bureau, 2024';
  const bgColor = props.bgColor || '#F5F0E6';
  
  const cat1Color = props.cat1Color || '#e26334';
  const cat2Color = props.cat2Color || '#5da7d1';
  const cat3Color = props.cat3Color || '#e9b5b3';
  
  const cat1Name = props.cat1Name || 'Espresso';
  const cat2Name = props.cat2Name || 'Cold Brew';
  const cat3Name = props.cat3Name || 'Instant';
  
  const titleFontFamily = props.titleFontFamily || 'Inter, sans-serif';

