  const safeFps = fps || 30;
  const safeSpring = (delay = 0, config = { damping: 15 }) => {
    return spring({ frame: Math.max(0, frame - delay), fps: safeFps, config });
  };

  const categories = [
    { name: cat1Name, color: cat1Color, points: [[15, 45], [20, 52], [25, 40], [18, 38], [22, 58], [28, 48]] },
    { name: cat2Name, color: cat2Color, points: [[70, 15], [82, 10], [75, 22], [65, 18], [88, 5], [78, 12]] },
    { name: cat3Name, color: cat3Color, points: [[45, 30], [52, 25], [40, 35], [48, 28], [55, 32], [58, 20]] }
  ];

  const xTicks = [0, 25, 50, 75, 100];
  const yTicks = [0, 20, 40, 60];

  const yAxisProgress = safeSpring(10, {damping: 20});
  const xAxisProgress = safeSpring(20, {damping: 20});
  const labelOp = safeSpring(20, {damping: 20});
