  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Props & Defaults
  const p = item.props || {};
  const authorName   = p.authorName   || 'Sam Kessler';
  const handle       = p.handle       || '@samkessler';
  const tweetText    = p.tweetText    || 'People giving PulseMetrics write access to their entire warehouse';
  const dateText     = p.dateText     || '6:15 PM \xB7 Mar 11, 2026';
