  const scriptFont = props.scriptFont;

  const safeFps = fps || 30;
  const safeSpring = (delay = 0, config = { damping: 15 }) => {
    return spring({ frame: Math.max(0, frame - delay), fps: safeFps, config });
  };

  // Animations
  const fadeOut = interpolate(frame, [durationInFrames - 15, durationInFrames - 1], [1, 0], {extrapolateRight: 'clamp'});
  
  const bgSwooshLen = 4000;
