  const frame = useCurrentFrame();
  const { fps, durationInFrames } = useVideoConfig();
  const p = item.props || {};
  const W = 1920, H = 1080;
  const ink = '#2c2620';
  const accent = p.accentColor || '#f7a8b8';
  const butter = '#ffd66e';
  const personRight = String(p.personSide || 'right') !== 'left';
  const ratio = Math.min(0.72, Math.max(0.45, Number(p.contentRatio) || 0.6));
  const splitX = Math.round(W * ratio);
