  const sway = Math.sin((frame / 140) * Math.PI * 2);
  const mask = personRight
    ? 'linear-gradient(90deg, #000 0 ' + splitX + 'px, transparent ' + splitX + 'px)'
    : 'linear-gradient(90deg, transparent 0 ' + (W - splitX) + 'px, #000 ' + (W - splitX) + 'px)';
